define(['mod_videotrack/core/api'],function(Api){'use strict';var MAX_BEACON_PAYLOAD_BYTES=60*1024;function sendSegment(config,state,start,end,Utils,Log){if(!config||!state||!window.navigator||typeof window.navigator.sendBeacon!=='function'){return false;}if(!config.beaconurl||!Utils||typeof Utils.isSafeBeaconUrl!=='function'||!Utils.isSafeBeaconUrl(config.beaconurl)){if(Log&&typeof Log.debug==='function'){Log.debug('mod_videotrack: sendBeacon skipped because the endpoint is not safe');}return false;}var args=Api.buildSegmentArgs(config,state,start,end,'beforeunload');if(!args){return false;}try{var payload=[{index:0,methodname:'mod_videotrack_save_segment',args:args}];var payloadText=JSON.stringify(payload);if(payloadText.length>MAX_BEACON_PAYLOAD_BYTES){if(Log&&typeof Log.debug==='function'){Log.debug('mod_videotrack: sendBeacon skipped because the payload is too large');}return false;}var blob=new Blob([payloadText],{type:'application/json'});if(blob.size>MAX_BEACON_PAYLOAD_BYTES){if(Log&&typeof Log.debug==='function'){Log.debug('mod_videotrack: sendBeacon skipped because the encoded payload is too large');}return false;}var accepted=window.navigator.sendBeacon(config.beaconurl,blob);if(!accepted&&Log&&typeof Log.debug==='function'){Log.debug('mod_videotrack: sendBeacon was not accepted by the browser');}return accepted;}catch(error){if(Log&&typeof Log.debug==='function'){Log.debug('mod_videotrack: sendBeacon failed - '+error);}return false;}}return{sendSegment:sendSegment};});
